Record rindex := RI { ri_vars : list (list kentry); ri_other : list kentry }.
Definition ri_bucket (ri : rindex) (k : option nat) : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$ri;R+^I$k;R!1+^J+Y-^JRN$k;R!1+^J+Y!1+^A+^K#12$n;R+Y!3'^C+^K!1'^L#3#1!1'^M#2").
Fixpoint mk_ri (fk : list kentry) : rindex :=
  match fk with
  | [] => RI [] []
  | K :: rest =>
      let t := mk_ri rest in
      match K with
      | KRange e' _ _ =>
          match vkey_of e' with
          | Some n => RI (lset (ri_vars t) n K) (ri_other t)
          | None => RI (ri_vars t) (K :: ri_other t)
          end
      | _ => t
      end
  end.
Definition find_rangeI (ri : rindex) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$ri;R+^I$e;R+P!2'^N!2'^O#2!1'^P#1#1").

