Record bctx : Type := BC {
  bc_fk : list kentry;      (* [comment removed for export] *)
  bc_ffk : list kentry;     (* [comment removed for export] *)
  bc_fs : list sfact;       (* [comment removed for export] *)
  bc_ri : rindex            (* [comment removed for export] *)
}.
(* [comment removed for export] *)
Definition mkbc0 (fk : list kentry) (fs : list sfact) : bctx :=
  BC fk (facts_of fk) fs (mk_ri (facts_of fk)).

Lemma lin_range_ext : forall r1 r2 c ts, (forall a, r1 a = r2 a) -> lin_range r1 c ts = lin_range r2 c ts.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S@0!2+_2+S+S!1+^J0%x;R+P1!2+_2+S+P!1+^A3!3,^F3#3#2!1#;#3!2'_K#;#5!2'_K#;#4-_2RN$p0;R!2+_2+S+S1#11$lo;R+S$hi;R+S-2RN$~R+21!2'_;,_<#;2!2,^S0!4,_:+S+S!2'_@#27!2'_@#18!2,^S0!4,_:+S+S!2'_@#28!2'_@#17!1,^Z0!1#<#4-^JRN$x;R!1+^J01;2$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01!3'_J#?#>#62$p0;R09::!2'_K#:#5!2'_K#:#4!3,^F3!4,_:+S+P#4#3#2$r1;R2$r2;R2$c;R+S$ts;R4$H;R%a;R+P!3+11!1#5#1!1#4#1!5'_13$ts;R4!3+11!3'_J#6#4#1!3'_J#5#4#1!2,61!3'_J#4#3!1,^B3$a0;R3-_2RN$p;R!2+_2+S+P%l;R4%~R!3+11!3'_J#8#6#1!3'_J#7#6#1!3+11!3'_J#9#75!3'_J#8#75#11$z;R+S$e;R+P!2$k;R+S$a;R+P$rest;R4$IH;R!3+11!3'_J#;#9#1!3'_J#:#9#1vd!6'X16$o;R1!3+11-^JRN$x;R!1+^J01#12$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01!3'_J#@#>#62$p0;R09::<!6'X1!3'_J#;#:#2$o;R1!3+11-^JRN$x;R!1+^J01;2$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01#42$p0;R09::<!2,61-^JRN$x;R!1+^J0162$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01!3'_J#>#=#52$p0;R0-_2RN$p0;R!2+_2+S+S1#11$lo;R+S$hi;R+S-2RN$~R+21!2'_;,_<#:2!2,^S0!4,_:+S+S!2'_@#2=!2'_@#1>!2,^S0!4,_:+S+S!2'_@#2>!2'_@#1=::!3'_J#<#:#2#1!1#<#3!1#8#3!3+11!3'_J#<#:?!3'_J#;#:?#2#1#2").
Qed.

(* [comment removed for export] *)
Ltac beq_crush rw :=
  repeat (first [ reflexivity
                | progress rw
                | lazymatch goal with
                  | |- ?L = _ =>
                      lazymatch L with
                      | (if ?c then _ else _) => destruct c
                      | (match ?x with _ => _ end) => destruct x
                      end
                  end ]).

Fixpoint erange_fB (fuel : nat) (bc : bctx) (e : expr) {struct fuel} : option (Z * Z) :=
  match fuel with
  | O => None
  | S fuel' =>
  let erange := erange_fB fuel' in
  match find_rangeI (bc_ri bc) e with
  | Some r => Some (clampi r)
  | None =>
  match (let l := lin_of e in
         if lin_trivial l then None
         else match lin_range (erange bc) (fst l) (snd l) with
              | Some (lo, hi) =>
                  (* [comment removed for export] *)
                  let q := zdiv64 lo in   (* [comment removed for export] *)
                  if Z.eqb q (zdiv64 hi) then Some ((lo - q * two64)%Z, (hi - q * two64)%Z) else None
              | None => None
              end) with
  | Some r => Some r
  | None =>
  match e with
  | ELit z => let v := zmod64 z in Some (v, v)   (* [comment removed for export] *)
  | EVar _ => None
  | EAlu op a b =>
      match op with
      | ALU_ADD =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if Z.ltb (ah + bh) two64 then Some ((al + bl)%Z, (ah + bh)%Z)
              else if Z.leb two64 (al + bl) then Some ((al + bl - two64)%Z, (ah + bh - two64)%Z)
              else None
          | _, _ => None
          end
      | ALU_SUB =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if Z.leb bh al then Some ((al - bh)%Z, (ah - bl)%Z)
              else if Z.ltb ah bl then Some ((al - bh + two64)%Z, (ah - bl + two64)%Z)
              else None
          | _, _ => None
          end
      | ALU_AND =>
          (* [comment removed for export] *)
          match (match b, erange bc a with
                 | ELit m, Some (al, ah) =>
                     let m' := (m mod two64)%Z in
                     let j := Z.log2 (m' + 1) in
                     if (Z.eqb (m' + 1) (2 ^ j) && Z.leb (al / 2 ^ j) (ah / 2 ^ j) && Z.eqb (al / 2 ^ j) (ah / 2 ^ j))%bool
                     then Some ((al mod 2 ^ j)%Z, (ah mod 2 ^ j)%Z)
                     else let jh := Z.log2 (two64 - m') in
                          if (Z.eqb (two64 - m') (2 ^ jh) && Z.ltb jh 64)%bool
                          then Some ((al - al mod 2 ^ jh)%Z, (ah - ah mod 2 ^ jh)%Z)
                          else None
                 | _, _ => None
                 end) with
          | Some r => Some r
          | None =>
          match erange bc a, erange bc b with
          | Some (_, ah), Some (_, bh) => Some (0%Z, Z.min ah bh)
          | Some (_, ah), None => Some (0%Z, ah)
          | None, Some (_, bh) => Some (0%Z, bh)
          | None, None => None
          end
          end
      | ALU_OR =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) => Some (Z.max al bl, mask_cover (Z.max ah bh))
          | _, _ => None
          end
      | ALU_XOR =>
          match erange bc a, erange bc b with
          | Some (_, ah), Some (_, bh) => Some (0%Z, mask_cover (Z.max ah bh))
          | _, _ => None
          end
      | ALU_SRL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s => Some ((al / 2 ^ s)%Z, (ah / 2 ^ s)%Z)
          | _, _ => None
          end
      | ALU_SRA =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              if Z.ltb ah (2 ^ 63) then Some ((al / 2 ^ s)%Z, (ah / 2 ^ s)%Z) else None
          | _, _ => None
          end
      | ALU_SLL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              if Z.ltb (ah * 2 ^ s) two64 then Some ((al * 2 ^ s)%Z, (ah * 2 ^ s)%Z) else None
          | _, _ => None
          end
      | ALU_SLTU =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if Z.ltb ah bl then Some (1%Z, 1%Z)
              else if Z.leb bh al then Some (0%Z, 0%Z) else Some (0%Z, 1%Z)
          | _, _ => Some (0%Z, 1%Z)
          end
      | ALU_SLT =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.ltb ah (2 ^ 63) && Z.ltb bh (2 ^ 63))%bool then
                (if Z.ltb ah bl then Some (1%Z, 1%Z)
                 else if Z.leb bh al then Some (0%Z, 0%Z) else Some (0%Z, 1%Z))
              else Some (0%Z, 1%Z)
          | _, _ => Some (0%Z, 1%Z)
          end
      end
  | EAluw op a b =>
      match op with
      | ALU_ADD =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              let bl' := if Z.eqb bl bh then zsigned64 bl else bl in
              let bh' := if Z.eqb bl bh then zsigned64 bh else bh in
              if (Z.leb 0 (al + bl') && Z.ltb (ah + bh') (2 ^ 31))%bool
              then Some ((al + bl')%Z, (ah + bh')%Z) else None
          | _, _ => None
          end
      | ALU_SUB =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.leb bh al && Z.ltb (ah - bl) (2 ^ 31))%bool
              then Some ((al - bh)%Z, (ah - bl)%Z) else None
          | _, _ => None
          end
      | ALU_SLL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              let s' := (s mod 32)%Z in
              if Z.ltb (ah * 2 ^ s') (2 ^ 31) then Some ((al * 2 ^ s')%Z, (ah * 2 ^ s')%Z) else None
          | _, _ => None
          end
      | ALU_SRL =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              let s' := (s mod 32)%Z in
              if (Z.ltb ah (2 ^ 32) && (Z.ltb 0 s' || Z.ltb ah (2 ^ 31)))%bool
              then Some ((al / 2 ^ s')%Z, (ah / 2 ^ s')%Z) else None
          | _, _ => None
          end
      | ALU_SRA =>
          match erange bc a, lit_shamt b with
          | Some (al, ah), Some s =>
              let s' := (s mod 32)%Z in
              if Z.ltb ah (2 ^ 31) then Some ((al / 2 ^ s')%Z, (ah / 2 ^ s')%Z) else None
          | _, _ => None
          end
      | _ => None
      end
  | EMd op a b =>
      match op with
      | M_MUL =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.leb 0 al && Z.leb 0 bl && Z.ltb (ah * bh) two64)%bool
              then Some ((al * bl)%Z, (ah * bh)%Z) else None
          | _, _ => None
          end
      | M_MULHU =>
          match erange bc a, erange bc b with
          | Some (al, ah), Some (bl, bh) =>
              if (Z.leb 0 al && Z.leb 0 bl)%bool
              then Some ((al * bl / two64)%Z, (ah * bh / two64)%Z) else None
          | _, _ => None
          end
      | M_DIVU =>
          match erange bc a, b with
          | Some (al, ah), ELit d =>
              let d' := (d mod two64)%Z in
              if Z.ltb 0 d' then Some ((al / d')%Z, (ah / d')%Z) else None
          | _, _ => None
          end
      | M_REMU =>
          match erange bc a, b with
          | Some (al, ah), ELit d =>
              let d' := (d mod two64)%Z in
              if Z.ltb 0 d' then Some (0%Z, Z.min ah (d' - 1)) else None
          | _, _ => None
          end
      | _ => None
      end
  | EMdw _ _ _ => None
  | EExt sx lo n a =>
      let w := (2 ^ (8 * Z.of_nat n))%Z in
      if sx then
        match lo, erange bc a with
        | O, Some (al, ah) =>
            if (Z.leb 0 al && Z.ltb ah (w / 2))%bool then Some (al, ah)
            else if (Nat.leb 1 n && Nat.leb n 8 && Z.leb (w / 2) al && Z.ltb ah w)%bool
                 then Some ((two64 - w + al)%Z, (two64 - w + ah)%Z) else None
        | _, _ => None
        end
      else
        match lo, erange bc a with
        | O, Some (al, ah) =>
            if (Z.leb 0 al && Z.ltb ah w)%bool then Some (al, ah) else Some (0%Z, Z.min (w - 1) (two64 - 1))
        | _, _ => Some (0%Z, Z.min (w - 1) (two64 - 1))
        end
  | EBlob sx k i n =>
      (* [comment removed for export] *)
      if sx then Some (0%Z, two64m1) else Some (0%Z, Z.min (2 ^ (8 * Z.of_nat n) - 1) (two64 - 1))%Z
  end
  end
  end
  end.

Definition erange0B (bc : bctx) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$bc;R+_L$e;R+P!3'_M'_N#2#1").

Definition erangeB (bc : bctx) (e : expr) : option (Z * Z) :=
  let r := erange0B bc e in
  let '(e', s) := deand e in
  if Z.eqb s 0 then r else
  (* [comment removed for export] *)
  let g := lin_galign (lin_of e) in
  let rnd := fun p : Z * Z => Some (round_itv g (fst p) (snd p)) in
  match erange0B bc (unlin (lin_of e')) with     (* [comment removed for export] *)
  | Some (lo', hi') =>
      if Z.leb s lo' then
        match r with
        | Some (lo, hi) => rnd (Z.max lo (lo' - s), Z.min hi hi')
        | None => rnd ((lo' - s)%Z, hi')
        end
      else match r with Some p => rnd p | None => None end
  | None => match r with Some p => rnd p | None => None end
  end.

Definition base_rangeB (bc : bctx) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S30!2+_2+S+S!2'_Q#5#4!2'_Q#6#5$bc;R+_L$e;R+P-PRN$e;R+P!1+^J0#18$z;R+S&v;R!2'_O#1'_P+S!2,^S0!4,_:+S+S#1#1$n;R+Y!2'_Q#3#2$op;R+0$a;R+P$b;R+P1$op;R+0$a;R+P$b;R+P1$op;R+F$a;R+P$b;R+P1$op;R+F$a;R+P$b;R+P1$sx;R+2$lo;R+Y$n;R+Y$e0;R+P2$sx;R+2$k;R+Y$i;R+S$n;R+Y2").

Definition ealignB (bc : bctx) (e : expr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$bc;R+_L$e;R+P!2'_R!2'_S!1'_T#2#1!1'_U#1").

Definition lin_nowrapB (bc : bctx) (e : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S20!2+_2+S+S!1+^A!2+_2+S+P$bc;R+_L$e;R+P&l;R!1'_V#1'_W-^JRN$x;R!1+^J0+2!3'_J!1'_Q#3!3'^>+S1#1!3'_X+S1#12$p;R0-_2RN$p;R!2+_2+S+S+2#11$lo;R+S$hi;R+S!2'^6!2'_;,_<#2!2'_=#1'_P,7").

Fixpoint srl_expandB (bc : bctx) (ts : list (Z * expr)) : Z * list (Z * expr) :=
  match ts with
  | [] => (0%Z, [])
  | (k, a) :: rest =>
      let '(c, ts') := srl_expandB bc rest in
      let keep := (c, lins_e k a ts') in
      match a with
      | EAlu ALU_SRL e (ELit s) =>
          let m := (2 ^ ((s mod two64) mod 64))%Z in
          if (Z.eqb (k mod m)%Z 0%Z && lin_nowrapB bc e)%bool then
            let q := (k / m)%Z in
            let le := lin_of e in
            if Z.leb ((s mod two64) mod 64) (ealignB bc e) then   (* [comment removed for export] *)
              ((c + q * fst le)%Z, fold_right (fun t acc => lins_e (q * fst t)%Z (snd t) acc) ts' (snd le))
            else
            ((c + q * fst le)%Z,
             lins_e (- q)%Z (srl_rem e m) (fold_right (fun t acc => lins_e (q * fst t)%Z (snd t) acc) ts' (snd le)))
          else keep
      | EAlu ALU_AND e (ELit mk) =>
          (* [comment removed for export] *)
          match highmask_s mk with
          | Some s =>
              if lin_nowrapB bc e then
                let le := lin_of e in
                ((c + k * fst le)%Z,
                 lins_e (- k)%Z (srl_rem e (2 ^ s)) (fold_right (fun t acc => lins_e (k * fst t)%Z (snd t) acc) ts' (snd le)))
              else keep
          | None => keep
          end
      | _ => keep
      end
  end.

Definition fact_nowrapB (bc : bctx) (e : expr) (hi : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!2+_2+S+S!1+^A!2+_2+S+P$bc;R+_L$e;R+P$hi;R+S&l;R!1'_V#2'_W-^JRN$x;R!1+^J0+2!3'_J!1'_Q#4!3'^>+S1#1!3'_X+S1#12$p;R0-_2RN$p;R!2+_2+S+S+2#11$a;R+S$b;R+S!2'^6!2'_=#1'_P!2'_=#5!2'_@#2'_P,7").

Definition sum_fact_xB (bc : bctx) (ts : list (Z * expr)) (lo hi : Z) : list sfact := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S60!2+_2+S+P!1+^A0!1+^A'_Y!1,^B'_Y!2+_2+S+S!2+_214$bc;R+_L$ts;R1$lo;R+S$hi;R+S-_2RN$x;R!2+_2+S12!2'_Z#4#31$c2;R+S$ts2;R1-^ARN$ts2;R!1+^A02#123$p;R0$l;R!1+^A0-2RN$~R+22!2'U#4,_<23!3,^F5!4,_:14#3!4,_:+S+S!2'_A#6#4!2'_A#5#4!1,^B5").

Fixpoint sum_factsB (bc : bctx) (kn : list kentry) : list sfact :=
  match kn with
  | [] => []
  | KRange e lo hi :: rest =>
      match e with
      | EVar _ => sum_factsB bc rest
      | _ =>
        match lin_of e with
        | (c, (_ :: _ :: _) as ts) =>
            if fact_nowrapB bc e hi then (ts, ((lo - c)%Z, (hi - c)%Z)) :: sum_fact_xB bc ts (lo - c)%Z (hi - c)%Z ++ sum_factsB bc rest
            else sum_factsB bc rest
        | _ => sum_factsB bc rest
        end
      end
  | _ :: rest => sum_factsB bc rest
  end.


