Definition lin_test_relB (bc : bctx) (c : Z) (ts : list (Z * expr)) (test : Z -> Z -> bool) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S30!1+^A!2+_2+S+P!2+_2+S+S!2+_201$bc;R+_L$c;R+S$ts;R0$test;R%~R+S%~R+S+2-^ARN$x;R!1+^A'_Y+2!1'a;#42,7$s;R'_Y$l;R!1+^A'_Y-_2RN$x;R!2+_22+2+2!5'a>!3,^F'_Y#2#1#4,_<,_<,71$p;R2$b;R+2-_2RN$p;R!2+_201+2#21$ts';R0$p0;R1-_2RN$p0;R!2+_2+S+S+2#11$lo0;R+S$hi0;R+S-2RN$b;R+2+2#52-^JRN$x;R!1+^J1+2!3'_J!1'_Q#<#;#42$p;R1-_2RN$p;R!2+_2+S+S+2#11$lo;R+S$hi;R+S!2#<!2'_@#2#5!2'_@#1#4,7,7").

Definition lin_testB (bc : bctx) (c : Z) (ts : list (Z * expr)) (test : Z -> Z -> bool) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S10!2+_2+S+S$bc;R+_L$c;R+S$ts;R!1+^A!2+_2+S+P$test;R%~R+S%~R+S+2-^JRN$x;R!1+^J0+2!3'_J!1'_Q#4#3#22$p;R0-_2RN$p;R!2+_2+S+S+2#11$lo;R+S$hi;R+S-2RN$~R+2+2!2#4#2#12,4!4'a?#7#6#5#4!4'a?#4#3#2#1").

Definition lin_srangeB (bc : bctx) (e : expr) : option (Z * Z) :=
  let l := lin_of e in
  let j := srl_scale_need (snd l) in
  if (if Z.leb 0 j then Z.leb j 24 else false) then   (* [comment removed for export] *)
    let sc := (2 ^ j)%Z in
    let ts := List.map (fun t => ((sc * fst t)%Z, snd t)) (snd l) in
    let '(c2, t2) := srl_expandB bc ts in
    let '(c3, t3) := (if has_srl t2 then srl_expandB bc t2 else (0%Z, t2)) in
    match lin_range (erangeB bc) (sc * fst l + c2 + c3)%Z t3 with
    | Some (lo', hi') =>
        let lo := zcdiv lo' sc in let hi := (hi' / sc)%Z in
        if (if Z.leb 0 lo then (if Z.leb lo hi then Z.ltb hi two64 else false) else false) then Some (lo, hi) else None
    | None => None
    end
  else None.

Definition lin_nowrapRB (bc : bctx) (e : expr) : bool :=
  let l := lin_of e in
  let '(c2, t2) := srl_expandB bc (snd l) in            (* [comment removed for export] *)
  if lin_testB bc (fst l + c2)%Z t2 (fun lo hi => (Z.leb 0 lo && Z.ltb hi two64)%bool) then true
  else (* [comment removed for export] *)
    match lin_srangeB bc e with Some _ => true | None => false end.

Definition lin_apart0B (bc : bctx) (b1 : expr) (k1 n1 : Z) (b2 : expr) (k2 n2 : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S10!1+^A!2+_2+S+P$bc;R+_L$b1;R+P$k1;R+S$n1;R+S$b2;R+P$k2;R+S$n2;R+S!2'^6!2'^6!2'a@#7#6!2'a@#7#3&l1;R!1'_V#6'_W&l2;R!1'_V#4'_W!4'aA#9!2'_A!2'_A!2'_@!3'^>+S0#1#4!3'^>+S0#2#7!2'aB!3'_X+S0#1!3'_X+S0#2$lo;R+S$hi;R+S!2'`?!2'_;#8#2!2'_;#1!1'`X#5").

Definition lin_apartB (bc : bctx) (b1 : expr) (k1 n1 : Z) (b2 : expr) (k2 n2 : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S00$bc;R+_L$b1;R+P$k1;R+S$n1;R+S$b2;R+P$k2;R+S$n2;R+S-2RN$~R+2+2!2'aC#6#32!7'aD#7#6#5#4#3#2#1,7").

Definition lin_brangeB (bc : bctx) (e : expr) : option (Z * Z) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S60!2+_2+S+S!1+^J0!1,^Z0!1+^A!2+_2+S+P!2+_230!2'_@#2#5$bc;R+_L$e;R+P&l;R!1'_V#1'_W-^ARN$x;R!1+^A'_Y1!1'a;#322$s;R'_Y$l0;R!1+^A'_Y-_2RN$x;R!2+_24+21!5'a>!3,^F'_Y#2#1!3'_X+S3#3,_<,_<,71$p;R4$b;R+2-_2RN$p;R!2+_2301#21$ts';R3$p0;R0-_2RN$p0;R!2+_2+S+S1#11$lo0;R+S$hi0;R+S-2RN$b;R+21#52-^JRN$x;R!1+^J01!3'_J!1'_Q#;!3'^>+S3#9#42$p;R0-_2RN$p;R!2+_2+S+S1#11$lo;R+S$hi;R+S&lo';R5+S&hi';R5+S-2RN$~R+21!2'^6!2'_;,_<#2!2'_=#1'_P2!2,^S0!4,_:+S+S#2#1222").

Definition xloB (bc : bctx) (e : expr) : option Z :=
  match e with
  | ELit z => Some (zlit64 z)
  | _ => match erangeB bc e with
         | Some (lo, _) => Some lo
         | None => match lin_brangeB bc e with
                   | Some (lo, _) => Some lo
                   | None => match lin_srangeB bc e with Some (lo, _) => Some lo | None => None end   (* [comment removed for export] *)
                   end
         end
  end.

Definition xhiB (bc : bctx) (e : expr) : option Z :=
  match e with
  | ELit z => Some (zlit64 z)
  | _ => match erangeB bc e with
         | Some (_, hi) => Some hi
         | None => match lin_brangeB bc e with
                   | Some (_, hi) => Some hi
                   | None => match lin_srangeB bc e with Some (_, hi) => Some hi | None => None end   (* [comment removed for export] *)
                   end
         end
  end.

Fixpoint xt_nowrapB (bc : bctx) (ts : xterms) : bool :=
  match ts with [] => true | (e, _) :: r => lin_nowrapRB bc e && xt_nowrapB bc r end.

Definition lin_ge0_scaledB (bc : bctx) (c : Z) (ts : list (Z * expr)) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!2+_2+S+P!1+^A0$bc;R+_L$c;R+S$ts;R1&j;R!1'aE#1+S-2RN$~R+2+2-2RN$~R+2+2!2'_=,_<#12!2'_;#1!1,_?|48;,72&sc;R!2'_>!1,_?|10;#1+S&ts';R!4'aF00$t;R0!4,_:+S+P!2'_K#2!3'^>+S+P#1!3'_X+S+P#1#31-_2RN$x;R!2+_2+S1+2!2'_Z#6#11$c2;R+S$t2;R1-_2RN$x;R!2+_2+S1+2-2RN$~R+2!2+_2+S1!1'aG#12!2'_Z#8#1!4,_:+S1,_<#11$c3;R+S$t3;R1!4'aA#:!2'_@!2'_@!2'_K#6#9#4#2#1$lo;R+S$~R+S!2'_;,_<#2,7").

Definition lin_ge0B (bc : bctx) (pos neg : xterms) : bool :=
  let al := ealignB bc in   (* [comment removed for export] *)
  (xt_nowrapB bc pos && xt_nowrapB bc neg &&
   (* [comment removed for export] *)
   (let c1 := (xt_const pos - xt_const neg)%Z in let t1 := lsub_e (xt_lin pos) (xt_lin neg) in
    if lin_testB bc c1 t1 (slack_test al c1 t1) then true
    else let '(c2, t2) := srl_expandB bc t1 in
         if lin_testB bc (c1 + c2)%Z t2 (slack_test2 al c1 t1 (c1 + c2)%Z t2) then true
         else (* [comment removed for export] *)
         if (if has_srl t2 then
               let '(c3, t3) := srl_expandB bc t2 in
               lin_testB bc (c1 + c2 + c3)%Z t3 (slack_test2 al c1 t1 (c1 + c2 + c3)%Z t3)
             else false) then true
         else (* [comment removed for export] *)
           lin_ge0_scaledB bc c1 t1))%bool.

Definition xinside0B (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S40!2+_2+P+S!4,_:+P+S#6#5!1,^B0!4,_:+P+S#3#2$bc;R+_L$b1;R+P$k1;R+S$n1;R+P$b2;R+P$k2;R+S$n2;R+P-2RN$~R+2+2!3'aH#7!3,^F012!3,^F0322!3'aH#7!3,^F03!3,^F0!4,_:+P+S#1,_<2!3,^F01!3,^F0!4,_:+P+S#4,_<2,7").

Definition xinside_numB (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S20!2+_2+S+S!2'_@#7#9$bc;R+_L$b1;R+P$k1;R+S$n1;R+P$b2;R+P$k2;R+S$n2;R+P-^JRN$x;R!1+^J+S+2!2'aI#7#32$lo2;R+S-^JRN$x;R!1+^J+S+2!2'aJ#8#42$hi2;R+S-2RN$~R+2+2!2'U#2#12-^JRN$x;R!1+^J0+2!2'`M#9#82$p;R0-_2RN$p;R!2+_2+S+S+2#11$lo1;R+S$hi1;R+S-^JRN$x;R!1+^J+S+2!2'aJ#<#92$h1;R+S-^JRN$x;R!1+^J+S+2!2'aI#=#72$l2;R+S!2'^6!2'_;1!2'_@#4#<!2'_;!2'_@!2'_@#3#<#2!2'_@1#1,7,7,7,7,7,7").

Definition xinsideB (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S20!7'aK#:#9#8#7#6#5#4!7'aK#;#:#9#8#7#6#5$bc;R+_L$b1;R+P$k1;R+S$n1;R+P$b2;R+P$k2;R+S$n2;R+P-2RN$~R+2+2!2'aC#6#32!7'aK#7#6#5#4#3#2#1-2RN$~R+2+2!1'aL#32-2RN$~R+2+2!7'aM#7#6#5#4#3#2#12,4-PRN$n1;R+P+2#48$z;R+S,7$n;R+Y!7'aK#8#7#6#5#4#3#2$op;R+0$a;R+P$b;R+P0$op;R+0$a;R+P$b;R+P0$op;R+F$a;R+P$b;R+P0$op;R+F$a;R+P$b;R+P0$sx;R+2$lo;R+Y$n;R+Y$e;R+P1$sx;R+2$k;R+Y$i;R+S$n;R+Y1,7").

Definition sub_itvB (bc : bctx) (b : expr) (k n : Z) (c : saddr) (m : expr) : bool :=
  if (if (expr_eqb b (a_base c) && Z.leb (a_off c) k)%bool then
        match xloB bc m with Some ml => Z.leb (k + n) (a_off c + ml) | None => false end
      else false)
  then true
  else (* [comment removed for export] *)
    if (Z.leb 0 n && Z.ltb n two64)%bool then xinsideB bc b k (ELit n) (a_base c) (a_off c) m else false.

Fixpoint kdisj_apartB (bc : bctx) (kn : list kentry) (b1 : expr) (k1 n1 : Z) (b2 : expr) (k2 n2 : Z) : bool :=
  match kn with
  | [] => false
  | KDisj c1 m1 c2 m2 :: rest =>
      if (if sub_itvB bc b1 k1 n1 c1 m1 then sub_itvB bc b2 k2 n2 c2 m2 else false) then true
      else if (if sub_itvB bc b1 k1 n1 c2 m2 then sub_itvB bc b2 k2 n2 c1 m1 else false) then true
      else kdisj_apartB bc rest b1 k1 n1 b2 k2 n2
  | _ :: rest => kdisj_apartB bc rest b1 k1 n1 b2 k2 n2
  end.

Definition ranges_apartB (bc : bctx) (b1 : expr) (k1 n1 : Z) (b2 : expr) (k2 n2 : Z) : bool :=
  if expr_eqb b2 b1 then (Z.leb (k1 + n1) k2 || Z.leb (k2 + n2) k1)%bool else   (* [comment removed for export] *)
  if (match base_rangeB bc b1, base_rangeB bc b2 with
      | Some (lo1, hi1), Some (lo2, hi2) =>
          (Z.leb (hi1 + k1 + n1) (lo2 + k2) || Z.leb (hi2 + k2 + n2) (lo1 + k1))%bool
      | _, _ => false
      end) then true
  else if kdisj_apartB bc (bc_fk bc) b1 k1 n1 b2 k2 n2 then true
  else lin_apartB bc b1 k1 n1 b2 k2 n2.

Definition sub_itv_xB (bc : bctx) (b : expr) (k : Z) (n : expr) (c : saddr) (m : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S00$bc;R+_L$b;R+P$k;R+S$n;R+P$c;R+_4$m;R+P!7'aN#6#5#4#3!1'aO#2!1'aP#2#1").

Fixpoint kdisj_apart_xB (bc : bctx) (kn : list kentry) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match kn with
  | [] => false
  | KDisj c1 m1 c2 m2 :: rest =>
      if (if sub_itv_xB bc b1 k1 n1 c1 m1 then sub_itv_xB bc b2 k2 n2 c2 m2 else false) then true
      else if (if sub_itv_xB bc b1 k1 n1 c2 m2 then sub_itv_xB bc b2 k2 n2 c1 m1 else false) then true
      else kdisj_apart_xB bc rest b1 k1 n1 b2 k2 n2
  | _ :: rest => kdisj_apart_xB bc rest b1 k1 n1 b2 k2 n2
  end.

Definition end_hiB (bc : bctx) (b : expr) (k : Z) (n : expr) (lo1 hi1 h1 : Z) : option Z := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S60!1+^J+S!1,^Z+S!2+_2+S+S-_2RN$p;R!2+_2+S+S0#11$z;R+S$ehi;R+S!2,^S+S#1-2RN$~R+20-2RN$~R+2+2!2'_;,_<!2'_@#6#82!2'_=!2'_@!2'_@#5#8#4'_P,72-^JRN$x;R!1+^J20!2'_I!1'`0#:!3'aQ,5!3'aQ,5#9!1,T#8#72$p;R2311-2RN$~R+20-2RN$~R+2+2!2'_;,_<!2'_@#7#92!2'_=!2'_@!2'_@#6#9#5'_P,72-^JRN$x;R!1+^J20!2'_I!1'`0#;!3'aQ,5!3'aQ,5#:!1,T#9#82$p;R2311$bc;R+_L$b;R+P$k;R+S$n;R+P$lo1;R+S$hi1;R+S$h1;R+S-PRN$n;R+P0#48$z;R+S1$n0;R+Y-2RN$~R+20-2RN$~R+2+2!2'_;,_<!2'_@#4#62!2'_=!2'_@!2'_@#3#6#2'_P,72-^JRN$x;R!1+^J20!2'_I!1'`0#8!3'aQ,5!3'aQ,5#7!1,T#6#52$p;R2311$op;R+0$a;R+P$b0;R+P4$op;R+0$a;R+P$b0;R+P4$op;R+F$a;R+P$b0;R+P4$op;R+F$a;R+P$b0;R+P4$sx;R+2$lo;R+Y$n0;R+Y$e;R+P5$sx;R+2$k0;R+Y$i;R+S$n0;R+Y5").

Definition ranges_apart_xB (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match n1, n2 with
  | ELit z1, ELit z2 => ranges_apartB bc b1 k1 (zlit64 z1) b2 k2 (zlit64 z2)
  | _, _ =>
    if (match base_rangeB bc b1, base_rangeB bc b2, xhiB bc n1, xhiB bc n2 with
        | Some (lo1, hi1), Some (lo2, hi2), Some h1, Some h2 =>
            if (Z.leb (hi1 + k1 + h1) (lo2 + k2) || Z.leb (hi2 + k2 + h2) (lo1 + k1))%bool then true
            else (* [comment removed for export] *)
            if match end_hiB bc b1 k1 n1 lo1 hi1 h1 with Some e1 => Z.leb e1 (lo2 + k2) | None => false end then true
            else match end_hiB bc b2 k2 n2 lo2 hi2 h2 with Some e2 => Z.leb e2 (lo1 + k1) | None => false end
        | _, _, _, _ => false
        end) then true
    else if kdisj_apart_xB bc (bc_fk bc) b1 k1 n1 b2 k2 n2 then true
    else if negb (shares_var b1 b2) then false
    else if lin_ge0B bc [(b2, k2)] [(b1, k1); (n1, 0%Z)] then true
    else lin_ge0B bc [(b1, k1)] [(b2, k2); (n2, 0%Z)]
  end.

Fixpoint disj_sidesB (bc : bctx) (kn : list kentry) (b1 : expr) (k1 n1 : Z) : list (saddr * expr) :=
  match kn with
  | [] => []
  | KDisj c1 m1 c2 m2 :: rest =>
      let r := disj_sidesB bc rest b1 k1 n1 in
      let r1 := if sub_itvB bc b1 k1 n1 c2 m2 then (c1, m1) :: r else r in
      if sub_itvB bc b1 k1 n1 c1 m1 then (c2, m2) :: r1 else r1
  | _ :: rest => disj_sidesB bc rest b1 k1 n1
  end.

Fixpoint disj_sides_xB (bc : bctx) (kn : list kentry) (b1 : expr) (k1 : Z) (n1 : expr) : list (saddr * expr) :=
  match kn with
  | [] => []
  | KDisj c1 m1 c2 m2 :: rest =>
      let r := disj_sides_xB bc rest b1 k1 n1 in
      let r1 := if sub_itv_xB bc b1 k1 n1 c2 m2 then (c1, m1) :: r else r in
      if sub_itv_xB bc b1 k1 n1 c1 m1 then (c2, m2) :: r1 else r1
  | _ :: rest => disj_sides_xB bc rest b1 k1 n1
  end.

Fixpoint in_sidesB (bc : bctx) (D : list (saddr * expr)) (b2 : expr) (k2 n2 : Z) : bool :=
  match D with
  | [] => false
  | (c, m) :: r => if sub_itvB bc b2 k2 n2 c m then true else in_sidesB bc r b2 k2 n2
  end.

Fixpoint in_sides_xB (bc : bctx) (D : list (saddr * expr)) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match D with
  | [] => false
  | (c, m) :: r => if sub_itv_xB bc b2 k2 n2 c m then true else in_sides_xB bc r b2 k2 n2
  end.

(* [comment removed for export] *)
Definition xinside_numB_br (bc : bctx) (br1 : option (Z * Z)) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match xloB bc b2, xhiB bc b2 with
  | Some lo2, Some hi2 =>
      if Z.eqb lo2 hi2 then
        match br1, xhiB bc n1, xloB bc n2 with
        | Some (lo1, hi1), Some h1, Some l2 => Z.leb (lo2 + k2) (lo1 + k1) && Z.leb (hi1 + k1 + h1) (lo2 + k2 + l2)
        | _, _, _ => false
        end
      else false
  | _, _ => false
  end.
Definition xinsideB_br (bc : bctx) (br1 : option (Z * Z)) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 8 "S20!7'aK#;#9#8#7#6#5#4!7'aK#<#:#9#8#7#6#5$bc;R+_L$br1;R!1+^J!2+_2+S+S$b1;R+P$k1;R+S$n1;R+P$b2;R+P$k2;R+S$n2;R+P-2RN$~R+2+2!2'aC#6#32!7'aK#8#6#5#4#3#2#1-2RN$~R+2+2!1'aL#32-2RN$~R+2+2!8'aR#8#7#6#5#4#3#2#12,4-PRN$n1;R+P+2#48$z;R+S,7$n;R+Y!7'aK#9#7#6#5#4#3#2$op;R+0$a;R+P$b;R+P0$op;R+0$a;R+P$b;R+P0$op;R+F$a;R+P$b;R+P0$op;R+F$a;R+P$b;R+P0$sx;R+2$lo;R+Y$n;R+Y$e;R+P1$sx;R+2$k;R+Y$i;R+S$n;R+Y1,7").
Definition sub_itvB_br (bc : bctx) (br : option (Z * Z)) (b : expr) (k n : Z) (c : saddr) (m : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S20!1'aO#2!1'aP#2$bc;R+_L$br;R!1+^J!2+_2+S+S$b;R+P$k;R+S$n;R+S$c;R+_4$m;R+P-2RN$~R+2+2-2RN$~R+2+2!2'^6!2'R#50!2'_;1#42-^JRN$x;R!1+^J+S+2!2'aI#7#12$ml;R+S!2'_;!2'_@#5#4!2'_@!1'aP#3#1,7,72,4-2RN$~R+2+2!2'^6!2'_;,_<#3!2'_=#3'_P2!8'aS#7#6#5#4!1,T#301#1,7").
Definition sub_itv_xB_br (bc : bctx) (br : option (Z * Z)) (b : expr) (k : Z) (n : expr) (c : saddr) (m : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S00$bc;R+_L$br;R!1+^J!2+_2+S+S$b;R+P$k;R+S$n;R+P$c;R+_4$m;R+P!8'aS#7#6#5#4#3!1'aO#2!1'aP#2#1").
Fixpoint disj_sidesB_br (bc : bctx) (br : option (Z * Z)) (kn : list kentry) (b1 : expr) (k1 n1 : Z) : list (saddr * expr) :=
  match kn with
  | [] => []
  | KDisj c1 m1 c2 m2 :: rest =>
      let r := disj_sidesB_br bc br rest b1 k1 n1 in
      let r1 := if sub_itvB_br bc br b1 k1 n1 c2 m2 then (c1, m1) :: r else r in
      if sub_itvB_br bc br b1 k1 n1 c1 m1 then (c2, m2) :: r1 else r1
  | _ :: rest => disj_sidesB_br bc br rest b1 k1 n1
  end.
Fixpoint disj_sides_xB_br (bc : bctx) (br : option (Z * Z)) (kn : list kentry) (b1 : expr) (k1 : Z) (n1 : expr) : list (saddr * expr) :=
  match kn with
  | [] => []
  | KDisj c1 m1 c2 m2 :: rest =>
      let r := disj_sides_xB_br bc br rest b1 k1 n1 in
      let r1 := if sub_itv_xB_br bc br b1 k1 n1 c2 m2 then (c1, m1) :: r else r in
      if sub_itv_xB_br bc br b1 k1 n1 c1 m1 then (c2, m2) :: r1 else r1
  | _ :: rest => disj_sides_xB_br bc br rest b1 k1 n1
  end.
Fixpoint in_sidesB_br (bc : bctx) (br : option (Z * Z)) (D : list (saddr * expr)) (b2 : expr) (k2 n2 : Z) : bool :=
  match D with
  | [] => false
  | (c, m) :: r => if sub_itvB_br bc br b2 k2 n2 c m then true else in_sidesB_br bc br r b2 k2 n2
  end.
Fixpoint in_sides_xB_br (bc : bctx) (br : option (Z * Z)) (D : list (saddr * expr)) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match D with
  | [] => false
  | (c, m) :: r => if sub_itv_xB_br bc br b2 k2 n2 c m then true else in_sides_xB_br bc br r b2 k2 n2
  end.

Definition mk_sprepB (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) : sprep := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S20!2+_2+_4+P!1,^B0$bc;R+_L$b1;R+P$k1;R+S$n1;R+P&br;R!2'`M#4#3!1+^J!2+_2+S+S!4,aT#1!2'aJ#5#2-PRN$n1;R+P!1+^A0#28$z1;R+S!6'aU#6#2!1'aV#6#5#4!1'aW#1$n;R+Y1$op;R+0$a;R+P$b;R+P1$op;R+0$a;R+P$b;R+P1$op;R+F$a;R+P$b;R+P1$op;R+F$a;R+P$b;R+P1$sx;R+2$lo;R+Y$n;R+Y$e;R+P1$sx;R+2$k;R+Y$i;R+S$n;R+Y1!6'aX#5#1!1'aV#5#4#3#2").

Definition ranges_apart_pB (bc : bctx) (sp : sprep) (b1 : expr) (k1 : Z) (n1 : expr)
           (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  let br2 := base_rangeB bc b2 in   (* [comment removed for export] *)
  match n1, n2 with
  | ELit z1, ELit z2 =>
      let m1 := zlit64 z1 in let m2 := zlit64 z2 in
      if expr_eqb b2 b1 then (Z.leb (k1 + m1) k2 || Z.leb (k2 + m2) k1)%bool else   (* [comment removed for export] *)
      if (match sp_rng sp, br2 with
          | Some (lo1, hi1), Some (lo2, hi2) =>
              (Z.leb (hi1 + k1 + m1) (lo2 + k2) || Z.leb (hi2 + k2 + m2) (lo1 + k1))%bool
          | _, _ => false
          end) then true
      else if in_sidesB_br bc br2 (sp_D sp) b2 k2 m2 then true
      else lin_apartB bc b1 k1 m1 b2 k2 m2
  | _, _ =>
    if (match sp_rng sp, br2, sp_h1 sp, xhiB bc n2 with
        | Some (lo1, hi1), Some (lo2, hi2), Some h1, Some h2 =>
            if (Z.leb (hi1 + k1 + h1) (lo2 + k2) || Z.leb (hi2 + k2 + h2) (lo1 + k1))%bool then true
            else (* [comment removed for export] *)
            if match end_hiB bc b1 k1 n1 lo1 hi1 h1 with Some e1 => Z.leb e1 (lo2 + k2) | None => false end then true
            else match end_hiB bc b2 k2 n2 lo2 hi2 h2 with Some e2 => Z.leb e2 (lo1 + k1) | None => false end
        | _, _, _, _ => false
        end) then true
    else if in_sides_xB_br bc br2 (sp_Dx sp) b2 k2 n2 then true
    else if negb (shares_var b1 b2) then false
    else if lin_ge0B bc [(b2, k2)] [(b1, k1); (n1, 0%Z)] then true
    else lin_ge0B bc [(b1, k1)] [(b2, k2); (n2, 0%Z)]
  end.

