Lemma sym_execTX_know : forall t K fuel first stops ss,
  s_know (sym_execTX segs t K fuel first stops ss) = s_know ss.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1+^A+^K!1'mS#1!1'hR1!1'hR#1$t;R'mQ$K;R+Y$fuel;R+Y$first;R+2$stops;R!1+^A+S$ss;R+hOvd!6'X02$l;R0!3+10#1!1'hR#2-hORN$s;R+hO!3+1023#11$s_pc;R+S$s_regs;R!1+^A+P$s_log;R!1+^A+iP$s_know;R!1+^A+^K$s_next;R+Y$s_resv;R!1+^J+_4!6$s_pc0;R+S$s_regs0;R!1+^A+P$s_log0;R!1+^A+iP$s_know0;R0$s_next0;R+Y$s_resv0;R!1+^J+_4!2,60!1'hR!6,iI#6#5#4#3#2#1#6#5#4#3#2#1!1'hR!8'mT/segs;#6#5#4#3#211!8'n0#6#5#4#3#211!2,602!3+10!1'hR!7'm[/segs;#6#5#4#3#2#13").
Qed.
(* [comment removed for export] *)
Definition sym_stepXBI (bc : bctx) (kx : kix) (K : nat) (i : instr) (ss : sym_state) (scr : scripts) : stepres :=
  match sym_stepBI bc kx segs i ss scr with
  | SOk ss' scs scr' =>
      if Nat.leb (s_next ss) (s_next ss')
      then SOk (cap_rd K i ss') (x_filterB bc ss ss' scs) scr'
      else SStop
  | SStop => SStop
  end.
Lemma sym_stepXBI_eq : forall K i ss scr,
  sym_stepXBI (mkbc (facts_of (s_know ss))) (mk_kix (s_know ss)) K i ss scr = sym_stepX segs K i ss scr.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1'hR#2!1'a<!1'_[0!5'j:1/segs;#3#2#1!1+^A+dT!1'h\#3!5'mN/segs;#4#3#2#1!1'hH0$K;R+Y$i;R+i2$ss;R+hO$scr;R+hPvd!6'X+i32$s;R+i3!3+1+i3-i3RN$x;R+i3+i3#12$ss';R+hO$scs;R3$scr';R+hP-2RN$~R+2+i3!2'`A!1'h\#642!3,i6!3'mJ#8#7#3!4'mF!1'a<!1'_[!1'hR#6#6#3#2#1,iB,iB!5'mN/segs;#5#4#3#2vd!4'mY#4#3#2#1!3+1+i3-i3RN$x;R+i3+i322$ss';R+hO$scs;R3$scr';R+hP-2RN$~R+2+i3!2'`A!1'h\#542!3,i6!3'mJ#7#6#3!4'mF!1'a<!1'_[!1'hR#5#5#3#2#1,iB,iB5!6'j916/segs;#3#2#1!5'n11/segs;#3#2#1!3+1+i3!6'n216#4#3#2#15").
Qed.
Fixpoint sym_execTXBI_go (bc : bctx) (kx : kix) (t : itab) (K : nat) (fuel : nat) (first : bool) (stops : list Z) (ss : sym_state) (ck : sym_state)
  : sym_state :=
  match fuel with
  | O => if s_clean ss then ss else ck
  | S f =>
      if (negb first && existsb (Z.eqb (s_pc ss)) stops)%bool then (if s_clean ss then ss else ck) else
      match itab_lookup t (s_pc ss) with
      | None => if s_clean ss then ss else ck
      | Some i =>
          match sym_stepXBI bc kx K i ss scr_nil with
          | SOk ss' [] _ => sym_execTXBI_go bc kx t K f false stops ss' (if s_clean ss' then ss' else ck)
          | _ => if s_clean ss then ss else ck
          end
      end
  end.
Definition sym_execTXBI (bc : bctx) (kx : kix) (t : itab) (K : nat) (fuel : nat) (first : bool) (stops : list Z) (ss : sym_state) : sym_state := ltac2:(Rpl.RP.run_i (rplG ()) 8 "S10!1'mS#1$bc;R+_L$kx;R+eF$t;R'mQ$K;R+Y$fuel;R+Y$first;R+2$stops;R!1+^A+S$ss;R+hO!9'n3#8#7#6#5#4#3#200").
Lemma sym_execTXBI_go_eq : forall t K fuel first stops ss ck,
  sym_execTXBI_go (mkbc (facts_of (s_know ss))) (mk_kix (s_know ss)) t K fuel first stops ss ck = sym_execTX_go segs t K fuel first stops ss ck.
