(* [comment removed for export] *)
Definition bkey (e : expr) : option nat := first_var e.
Record binfo := BI { bi_base : expr; bi_br : option (Z * Z) }.
Record ntab := NT { nt_vars : list (list (expr * positive)); nt_other : list (expr * positive); nt_next : positive; nt_info : ptree binfo }.
Definition nt_empty : ntab := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!2+_2+P+e=!4,oJ!1,^B!1+^A0!1,^B0,`9!1,h<+oK").
Fixpoint alookupE (l : list (expr * positive)) (b : expr) : option positive :=
  match l with
  | [] => None
  | (b', id) :: rest => if expr_eqb b b' then Some id else alookupE rest b
  end.
Definition nt_bucket (t : ntab) (k : option nat) : list (expr * positive) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S10!2+_2+P+e=$t;R+oL$k;R!1+^J+Y-^JRN$k;R!1+^J+Y!1+^A0#12$n;R+Y!3'^C0!1'oM#3#1!1'oN#2").
Definition nt_add (t : ntab) (k : option nat) (p : expr * positive) (bi : binfo) : ntab := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S30!2+_2+P+e=!1'oO#5!1'oO#4$t;R+oL$k;R!1+^J+Y$p;R0$bi;R+oK-^JRN$k;R!1+^J+Y+oL#32$n;R+Y!4,oJ!4'^D0!1'oM#5#1#3!1'oN#5!1'gS1!4'eB+oK1#2!1'oP#5!4,oJ!1'oM#4!3,^F0#2!1'oN#4!1'gS2!4'eB+oK2#1!1'oP#4").
Definition intern (bc : bctx) (t : ntab) (b : expr) : positive * binfo * ntab := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!2+_2+e=+oK!2,oT#3!2'`M#5#3$bc;R+_L$t;R+oL$b;R+P&k;R!1'oQ#1!1+^J+Y-^JRN$x;R!1+^J+e=!2+_20+oL!2'oR!2'oS#3#1#22$id;R+e=!4,_:0+oL!4,_:+e=+oK#1-^JRN$x;R!1+^J+oK+oK!3'e@+oK!1'oP#4#12$bi;R+oK#11#4&id;R!1'oO#3+e=&bi;R1+oK!4,_:0+oL!4,_:+e=+oK#2#1!4'oU#5#3!4,_:+P+e=#4#2#1").

Definition NTI (bc : bctx) (t : ntab) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S20!1+^J+Y!2+_2+P+e=$bc;R+_L$t;R+oL!2+^8%k;R0%b;R+P%id;R+e=%~R!3'oV1!4,_:+P+e=#2#1!2'oS#4#3!2+^8!3+10#4!1'oQ#3!2+^8!3+1!1+^J+oK!3'e@+oK!1'oP#5#2!2,^S+oK!2,oT#3!2'`M#6#3!2'gO#2!1'oO#5%k;R0%b;R+P%id;R+e=%id';R+e=%~R!3'oV1!4,_:+P+e=#3#2!2'oS#5#4%~R!3'oV1!4,_:+P+e=#4#2!2'oS#6#5!3+1+e=#4#3").

Lemma nt_bucket_empty : forall k, nt_bucket nt_empty k = [].
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!2+_2+P+e=!1+^A0!1,^B0!3+11-YRN$n;R+Y1#122$m;R+Y22!2,612$k;R!1+^J+Y-^JRN$o;R!1+^J+Y!3+11!2'oS'oW#12#12$n;R+Y!1$n;R+Yvdvd-YRN$n;R+Y3#124$n;R+Y!1$n;R+Y4#13!3+11!2'oS'oW!2,^S+Y#12#1vd4!3+11!2'oS'oW!1,^Z+Y2").
Qed.
Lemma NTI_empty : forall bc, NTI bc nt_empty.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S<0!1+^J+Y!2+_2+P+e=!3'oV1!4,_:+P+e=#2#1!2'oS'oW#3!1+^J+oK!1'oP'oW!1'oO'oW!4,_:+P+e=#3#2!2'oS'oW#4!3'oV167!3'oV1!4,_:+P+e=#4#2!2'oS'oW#5!1+^A1!1,^B1$bc;R+_L!4,h>%k;R0%b;R+P%id;R+e=%~R2!2+^8!3+10#4!1'oQ#3!2+^8!3+13!3'e@+oK4#2!2,^S+oK!2,oT#3!2'`M#5#3!2'gO#25%k;R0%b;R+P%id;R+e=%id';R+e=%~R8%~R9!3+1+e=#4#3$k;R0$b;R+P$id;R+e=$~R2&H;R!6'8:7$l;R:!3'oV1!4,_:+P+e=#4#3#1#1;!1'oX#4!3'oV16;!2'<!2+^8!3+10#5!1'oQ#4!2+^8!3+13!3'e@+oK4#3!2,^S+oK!2,oT#4!2'`M#6#4!2'gO#35#1$k;R0$b;R+P$id;R+e=$id';R+e=$~R8$~R9&H0;R!6'8:!2'oS'oW#6$l;R:!3'oV1!4,_:+P+e=#6#4#1#1;!1'oX#6!3'oV1!4,_:+P+e=#5#3;&H;R!6'8:!2'oS'oW#7$l;R:!3'oV1!4,_:+P+e=#7#6#1#3;!1'oX#7!3'oV1!4,_:+P+e=#6#5;!2'<!3+1+e=#6#5#2").
